// RabbitMQ: declare exchange, queue, and binding
await channel.assertExchange('orders', 'topic', { durable: true });
await channel.assertQueue('high-value-orders', { durable: true });

// Binding: route messages with routing key 'order.placed.premium.*'
await channel.bindQueue(
  'high-value-orders',   // destination queue
  'orders',              // source exchange
  'order.placed.premium.*'  // binding key (topic pattern)
);
// Now only premium order events reach this queue

// RabbitMQ: manual acknowledgment after processing
channel.consume('orders', async (msg) => {
  if (msg === null) return;
  try {
    await db.orders.insert(JSON.parse(msg.content.toString()));
    channel.ack(msg);          // ACK only after DB write commits
  } catch (err) {
    channel.nack(msg, false, true);  // requeue on failure
  }
}, { noAck: false });  // disable auto-ack

